#!/usr/bin/env bun
/**
 * theme-core sync — (re)generates the theme's src/routes shim tree.
 *
 * Every route file in a theme is a one-line delegation into @panomc/theme-core
 * (via the $pano vite alias). This script owns that tree: on a core upgrade a
 * new route materializes as a new shim file, a removed one disappears, and the
 * theme author never edits src/routes by hand.
 *
 * Ejecting: put the marker  @theme-core-eject  anywhere in a generated file
 * (JS comment or HTML comment) and sync will never touch that file again —
 * the author owns it from that point on.
 *
 * It also refreshes plugin-contracts/ (snapshots of the installed plugins' view contracts, printing the
 * views that changed) and writes core-meta.json, the data the backend reads from theme.config.js.
 *
 * Run from the THEME's root: bun node_modules/@panomc/theme-core/bin/sync.js
 */
import { mkdirSync, writeFileSync, readFileSync, existsSync, readdirSync, statSync, rmSync, copyFileSync, realpathSync } from "node:fs";
import { join, dirname, relative, sep, isAbsolute } from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { createRequire } from "node:module";
import { pc } from "./ui.js";
import { createRouteMap } from "../src/kit/route-map.js";
import { pullContracts, writeCoreMeta } from "./contracts.js";

// Refuse to run inside the engine package itself: a run from there once wrote a full shim tree into bin/.
{
  const real = (path) => {
    try {
      return realpathSync(path);
    } catch {
      return path;
    }
  };
  const packageDir = real(join(dirname(fileURLToPath(import.meta.url)), ".."));
  const inside = relative(packageDir, real(process.cwd()));

  if (inside === "" || (!inside.startsWith("..") && !isAbsolute(inside))) {
    console.error(`${pc.red("x")} theme-core sync: run theme-core sync from a theme folder`);
    process.exit(1);
  }
}

const EJECT_MARKER = "@theme-core-eject";
const HEADER_JS = "// AUTO-GENERATED by theme-core sync — do not edit.\n// To take ownership of this file, add an eject comment (see theme-core docs).\n";
const HEADER_SVELTE = "<!-- AUTO-GENERATED by theme-core sync — do not edit. To take ownership, add an eject comment (see theme-core docs). -->\n";

const reexport = (what, from) => `${HEADER_JS}export { ${what} } from "${from}";\n`;

const renderPage = (name, from, props = "{data}") =>
  `${HEADER_SVELTE}<script>
  import ${name} from "${from}";

  export let data;
</script>

<${name} ${props === "none" ? "" : props === "{data}" ? "{data}" : props}/>
`;

const wrapLayout = (name, from) =>
  `${HEADER_SVELTE}<script>
  import ${name} from "${from}";
</script>

<${name}><slot /></${name}>
`;

const pagePair = (route, component, pagePath, props = "{data}") => [
  {
    path: `${route}/+page.js`,
    content: reexport("load", `$pano/lib/pages/${pagePath}`),
  },
  {
    path: `${route}/+page.svelte`,
    content: renderPage(component, `$pano/lib/pages/${pagePath}`, props),
  },
];

const layoutPair = (route, component, layoutPath) => [
  {
    path: `${route}/+layout.js`,
    content: reexport("load", `$pano/lib/layouts/${layoutPath}`),
  },
  {
    path: `${route}/+layout.svelte`,
    content: wrapLayout(component, `$pano/lib/layouts/${layoutPath}`),
  },
];

/**
 * The view catalogue routes (doc 02 section 7): theme dev mode only. A generated file never imports catalogue
 * code statically: `dev` from `$app/environment` is a build-time constant, so a production build drops the
 * dynamic import and its chunk, and the routes answer 404. (`ssr` is on in a production build so that the 404
 * is a real status and not an empty shell; in dev the catalogue renders in the browser only.)
 */
const catalogueLoad = (module, run) => `${HEADER_JS}import { dev } from "$app/environment";
import { error } from "@sveltejs/kit";

export const ssr = !dev;

export const load = async (event) => {
  const m = dev ? await import("$pano/routes/catalogue/${module}.js") : null;
  if (!m) throw error(404, "Not found");
  return m.${run}(event);
};
`;

const cataloguePage = `${HEADER_SVELTE}<script>
  export let data;
</script>

<svelte:component this={data.component} {data} />
`;

/** The JSON route runs without the root layout, so it sets the theme config itself (the registry waits for it). */
const catalogueServer = () => {
  const hasConfig = existsSync(join(process.cwd(), "theme.config.js"));

  return `${HEADER_JS}import { dev } from "$app/environment";
import { error } from "@sveltejs/kit";
${hasConfig ? `import themeConfig from "../../../../../theme.config.js";\nimport { setThemeConfig } from "$pano/registry/index.js";\n\nsetThemeConfig(themeConfig);\n` : ""}
export const GET = async (event) => {
  const m = dev ? await import("$pano/routes/catalogue/views-json.js") : null;
  if (!m) throw error(404, "Not found");
  return m.GET(event);
};
`;
};

const CATALOGUE_FILES = [
  { path: "(theme)/__pano/views/+page.js", content: catalogueLoad("list", "load") },
  { path: "(theme)/__pano/views/+page.svelte", content: cataloguePage },
  { path: "(theme)/__pano/views/[ns]/[view]/+page.js", content: catalogueLoad("stage", "load") },
  { path: "(theme)/__pano/views/[ns]/[view]/+page.svelte", content: cataloguePage },
  { path: "(theme)/__pano/views.json/+server.js", content: catalogueServer() },
];

/** The canonical Pano theme route tree. Grouping names are part of the theme
 *  contract: RootLayout keys off "(theme-settings)" to suppress MainLayout. */
const BASE_FILES = [
  // ---- root
  {
    path: "+layout.js",
    content: `${HEADER_JS}import themeConfig from "../../theme.config.js";
import { setThemeConfig } from "$pano/registry/index.js";

// Module side effect: the registry is populated on server and client before
// any load function runs.
setThemeConfig(themeConfig);

export { load } from "$pano/routes/root-layout-load.js";
`,
  },
  {
    path: "+layout.svelte",
    content: `${HEADER_SVELTE}<script>
  import RootLayout from "$pano/routes/RootLayout.svelte";

  export let data;
</script>

<RootLayout {data}><slot /></RootLayout>
`,
  },
  {
    path: "+layout.server.js",
    content: reexport("loadServer as load", "$pano/lib/layouts/AppLayout.svelte"),
  },
  {
    path: "+error.svelte",
    content: `${HEADER_SVELTE}<script>
  import Error from "$pano/lib/pages/ErrorPage.svelte";
</script>

<Error />
`,
  },

  // ---- (plugin-ui) catch-all host
  {
    path: "(plugin-ui)/[...path]/+layout.js",
    content: reexport("load", "$pano/routes/plugin-ui/layout.js"),
  },
  {
    path: "(plugin-ui)/[...path]/+layout.svelte",
    content: `${HEADER_SVELTE}<script>
  import Layout from "$pano/routes/plugin-ui/Layout.svelte";

  export let data;
</script>

<Layout {data}><slot /></Layout>
`,
  },
  {
    path: "(plugin-ui)/[...path]/+page.js",
    content: reexport("load", "$pano/routes/plugin-ui/page.js"),
  },
  {
    path: "(plugin-ui)/[...path]/+page.svelte",
    content: `${HEADER_SVELTE}<script>
  import Page from "$pano/routes/plugin-ui/Page.svelte";

  export let data;
</script>

<Page {data} />
`,
  },

  // ---- (theme) group
  { path: "(theme)/+layout.js", content: `${HEADER_JS}` },
  { path: "(theme)/+layout.svelte", content: `${HEADER_SVELTE}<slot />\n` },
  ...pagePair("(theme)", "Home", "HomePage.svelte"),
  ...pagePair("(theme)/activate", "ActivateEmailPage", "ActivateEmailPage.svelte"),
  ...pagePair("(theme)/activate-new-email", "ConfirmNewEmailPage", "ConfirmNewEmailPage.svelte"),
  ...layoutPair("(theme)/login", "AuthLayout", "AuthLayout.svelte"),
  ...pagePair("(theme)/login", "LoginPage", "LoginPage.svelte"),
  ...pagePair("(theme)/notifications", "NotificationsPage", "NotificationsPage.svelte"),
  ...pagePair("(theme)/player/[player]", "PlayerDetailPage", "PlayerDetailPage.svelte"),
  ...pagePair("(theme)/post/[url]", "PostDetailPage", "PostDetailPage.svelte"),
  // The posts feed is always reachable here, whatever the admin picked as the home page (doc 01 section 9).
  ...pagePair("(theme)/posts", "Home", "HomePage.svelte"),
  ...pagePair("(theme)/preview/post/[id]", "PreviewPostPage", "PreviewPostPage.svelte", 'post="{data.post}"'),
  ...layoutPair("(theme)/profile", "ProfileLayout", "ProfileLayout.svelte"),
  ...pagePair("(theme)/profile", "ProfilePage", "profile/ProfilePage.svelte"),
  ...pagePair("(theme)/profile/settings", "SettingsPage", "profile/SettingsPage.svelte"),
  ...layoutPair("(theme)/register", "AuthLayout", "AuthLayout.svelte"),
  ...pagePair("(theme)/register", "RegisterPage", "RegisterPage.svelte"),
  ...pagePair("(theme)/renew-password", "RenewPasswordPage", "RenewPasswordPage.svelte"),
  ...layoutPair("(theme)/reset-password", "AuthLayout", "AuthLayout.svelte"),
  ...pagePair("(theme)/reset-password", "ResetPasswordPage", "ResetPasswordPage.svelte", "none"),
  ...pagePair("(theme)/rules", "RulesPage", "RulesPage.svelte"),
  ...pagePair("(theme)/support", "SupportPage", "SupportPage.svelte"),
  ...layoutPair("(theme)/ticket", "TicketsLayout", "TicketsLayout.svelte"),
  ...pagePair("(theme)/ticket/[id]", "TicketDetailPage", "ticket/TicketDetailPage.svelte"),
  ...pagePair("(theme)/ticket/create", "CreateTicketPage", "ticket/CreateTicketPage.svelte"),
  ...layoutPair("(theme)/tickets", "TicketsLayout", "TicketsLayout.svelte"),
  ...pagePair("(theme)/tickets", "TicketsPage", "profile/TicketsPage.svelte"),
  {
    path: "(theme)/plugins/[pluginId]/resources/plugin-ui/client/[fileName]/+server.js",
    content: reexport("GET", "$pano/routes/plugins-client-file.js"),
  },
  {
    // Files of a plugin's UI package (doc 02 section 6); the handler is `routes/plugins-ui-file.js`.
    // `plugin-ui/client/[fileName]` above is more specific and keeps its own handler.
    path: "(theme)/plugins/[pluginId]/resources/plugin-ui/[kind]/[...file]/+server.js",
    content: reexport("GET", "$pano/routes/plugins-ui-file.js"),
  },
  {
    path: "(theme)/theme-api/languages/[language].json/+server.js",
    content: reexport("GET", "$pano/routes/theme-api-languages.js"),
  },
  {
    path: "(theme)/theme-api/licenses.json/+server.js",
    content: reexport("GET", "$pano/routes/theme-api-licenses.js"),
  },
  ...CATALOGUE_FILES,

  // ---- (theme-settings) group (name is contractual — see RootLayout)
  {
    path: "(theme-settings)/theme-settings/+layout.js",
    content: reexport("load", "$pano/lib/layouts/ThemeSettingsLayout.svelte"),
  },
  {
    path: "(theme-settings)/theme-settings/+layout.server.js",
    content: reexport("loadServer as load", "$pano/lib/layouts/ThemeSettingsLayout.svelte"),
  },
  {
    path: "(theme-settings)/theme-settings/+layout.svelte",
    content: wrapLayout("ThemeSettingsLayout", "$pano/lib/layouts/ThemeSettingsLayout.svelte"),
  },
  ...pagePair("(theme-settings)/theme-settings", "ThemeSettingsPage", "ThemeSettingsPage.svelte"),
];

/**
 * Host-provides stubs: @panomc/sdk's core/js modules import a handful of
 * modules from "$lib/..." by contract — the HOST app must supply them. In a
 * thin theme they are one-line re-exports into the core engine.
 */
const LIB_STUBS = [
  {
    path: "variables.js",
    content: `${HEADER_JS}export * from "$pano/lib/variables.js";\n`,
  },
  {
    path: "Store.js",
    content: `${HEADER_JS}export * from "$pano/lib/Store.js";\n`,
  },
  {
    path: "api.util.js",
    content: `${HEADER_JS}export * from "$pano/lib/api.util.js";\nexport { default } from "$pano/lib/api.util.js";\n`,
  },
  {
    path: "PluginAPI.js",
    content: `${HEADER_JS}export * from "$pano/lib/PluginAPI.js";\n`,
  },
  {
    path: "components/ToastContainer.svelte",
    content: `${HEADER_SVELTE}<script context="module">
  export { show } from "$pano/lib/components/ToastContainer.svelte";
</script>

<script>
  import ToastContainer from "$pano/lib/components/ToastContainer.svelte";
</script>

<ToastContainer />
`,
  },
];

/**
 * lang/ is GENERATED: core ships the base translation trees (new i18n keys
 * arrive with a core bump instead of rendering as raw keys); a theme adds or
 * replaces keys via lang-overrides/<locale>.json. Deep merge, additive only —
 * an overlay cannot delete a base key, so core additions always surface.
 */
function deepMerge(base, overlay) {
  const out = { ...base };
  for (const [k, v] of Object.entries(overlay)) {
    out[k] =
      v && typeof v === "object" && !Array.isArray(v) && typeof out[k] === "object"
        ? deepMerge(out[k] ?? {}, v)
        : v;
  }
  return out;
}

function syncLang() {
  const coreLangDir = join(dirname(fileURLToPath(import.meta.url)), "..", "lang");
  const overrideDir = join(process.cwd(), "lang-overrides");
  const outDir = join(process.cwd(), "lang");
  mkdirSync(outDir, { recursive: true });

  let merged = 0;
  for (const file of readdirSync(coreLangDir)) {
    if (!file.endsWith(".json")) continue;
    const base = JSON.parse(readFileSync(join(coreLangDir, file), "utf-8"));
    const overridePath = join(overrideDir, file);
    const overlay = existsSync(overridePath)
      ? JSON.parse(readFileSync(overridePath, "utf-8"))
      : {};
    writeFileSync(
      join(outDir, file),
      JSON.stringify(deepMerge(base, overlay), null, 2) + "\n",
    );
    merged++;
  }

  // Extra locales: an override file with no matching core base (e.g. de.json)
  // becomes a NEW language. Its base is core en-US, so untranslated keys fall
  // back to English instead of rendering as raw keys. The locale only shows up
  // on the site if an admin has defined a locale with the same code in the
  // panel — the theme file alone doesn't add it to the language picker.
  if (existsSync(overrideDir)) {
    const enBase = JSON.parse(readFileSync(join(coreLangDir, "en-US.json"), "utf-8"));
    for (const file of readdirSync(overrideDir)) {
      if (!file.endsWith(".json") || existsSync(join(coreLangDir, file))) continue;
      const overlay = JSON.parse(readFileSync(join(overrideDir, file), "utf-8"));
      writeFileSync(
        join(outDir, file),
        JSON.stringify(deepMerge(enBase, overlay), null, 2) + "\n",
      );
      merged++;
    }
  }

  syncPluginLang(overrideDir, outDir);
  return merged;
}

/**
 * Plugin texts of a theme (doc 03 section 5.1): `lang-overrides/plugins/<folder>/<locale>.json`
 * becomes `lang/<locale>.plugins.json` = `{ "<folder>": { ... } }`, one file per locale with at
 * least one plugin file. Plugin strings stay out of `lang/<locale>.json`, which the panel lists as
 * the theme's originals. A `<locale>.plugins.json` with no source any more is removed.
 */
function syncPluginLang(overrideDir, outDir) {
  const pluginsDir = join(overrideDir, "plugins");
  /** @type {Map<string, Record<string, unknown>>} */
  const byLocale = new Map();

  if (existsSync(pluginsDir)) {
    for (const folder of readdirSync(pluginsDir).sort()) {
      const folderDir = join(pluginsDir, folder);
      if (!statSync(folderDir).isDirectory()) continue;
      for (const file of readdirSync(folderDir).sort()) {
        if (!file.endsWith(".json")) continue;
        const locale = file.slice(0, -".json".length);
        const path = join(folderDir, file);
        let tree;
        try {
          tree = JSON.parse(readFileSync(path, "utf-8"));
        } catch (error) {
          throw new Error(`theme-core sync: ${relative(process.cwd(), path)} is not valid JSON (${error.message})`);
        }
        if (!tree || typeof tree !== "object" || Array.isArray(tree)) {
          throw new Error(`theme-core sync: ${relative(process.cwd(), path)} must hold a JSON object`);
        }
        if (!byLocale.has(locale)) byLocale.set(locale, {});
        byLocale.get(locale)[folder] = tree;
      }
    }
  }

  for (const [locale, trees] of byLocale) {
    writeFileSync(join(outDir, `${locale}.plugins.json`), JSON.stringify(trees, null, 2) + "\n");
  }

  for (const file of readdirSync(outDir)) {
    if (file.endsWith(".plugins.json") && !byLocale.has(file.slice(0, -".plugins.json".length))) {
      rmSync(join(outDir, file), { force: true });
    }
  }
}

/**
 * tokens.scss backfill: `new` scaffolds before dependencies exist, so its
 * commented token menu can't be generated then (the file carries a placeholder
 * marker instead). Once @panomc/sdk is installed, fill the menu in. Only the
 * placeholder is ever replaced — a tokens.scss the author touched is theirs.
 */
function backfillTokens() {
  const TOKENS_PLACEHOLDER = "(token list unavailable at scaffold time";
  const tokensPath = join(process.cwd(), "src", "styles", "tokens.scss");
  if (!existsSync(tokensPath)) return;
  const current = readFileSync(tokensPath, "utf-8");
  if (!current.includes(TOKENS_PLACEHOLDER)) return;
  let sdkDir;
  try {
    sdkDir = dirname(createRequire(join(process.cwd(), "package.json")).resolve("@panomc/sdk/package.json"));
  } catch {
    return;
  }
  const lines = [];
  for (const [file, label] of [
    ["core/scss/custom-bootstrap.scss", "Colors, radius, typography (Bootstrap layer)"],
    ["core/scss/themes.scss", "Named dark themes"],
  ]) {
    const src = readFileSync(join(sdkDir, file), "utf-8");
    const vars = [...src.matchAll(/^\$([\w-]+)\s*:\s*([^;]*?)\s*!default;/gm)]
      .filter(([, , value]) => !value.includes("\n"));
    if (vars.length) {
      lines.push(`// ── ${label} ${"─".repeat(Math.max(3, 46 - label.length))}`);
      for (const [, varName, value] of vars) lines.push(`// $${varName}: ${value};`);
      lines.push("");
    }
  }
  if (!lines.length) return;
  const start = current.indexOf("// " + TOKENS_PLACEHOLDER);
  const endMarker = "for every variable)";
  const end = current.indexOf(endMarker, start);
  if (start === -1 || end === -1) return;
  writeFileSync(
    tokensPath,
    current.slice(0, start) + lines.join("\n") + current.slice(end + endMarker.length + 1),
  );
  console.log("theme-core sync: filled in the token menu in src/styles/tokens.scss");
}

/**
 * Static assets the engine's components and SCSS reference by absolute URL
 * (/assets/img/logo.svg, quicksand fonts, FontAwesome webfonts). A thin theme
 * doesn't carry them in git — they're synced into static/assets/ here.
 * Existing files are NEVER overwritten, so a theme can brand its own
 * logo.svg (or any other asset) by simply replacing the file.
 */
function syncStaticAssets() {
  const themeRequire = createRequire(join(process.cwd(), "package.json"));
  const staticDir = join(process.cwd(), "static");
  let copied = 0;

  const copyTree = (fromDir, toDir) => {
    if (!existsSync(fromDir)) return;
    mkdirSync(toDir, { recursive: true });
    for (const entry of readdirSync(fromDir)) {
      const from = join(fromDir, entry);
      const to = join(toDir, entry);
      if (statSync(from).isDirectory()) {
        copyTree(from, to);
      } else if (!existsSync(to)) {
        copyFileSync(from, to);
        copied++;
      }
    }
  };

  const engineAssets = join(dirname(fileURLToPath(import.meta.url)), "..", "assets");
  copyTree(join(engineAssets, "img"), join(staticDir, "assets", "img"));
  if (existsSync(join(engineAssets, "robots.txt")) && !existsSync(join(staticDir, "robots.txt"))) {
    copyFileSync(join(engineAssets, "robots.txt"), join(staticDir, "robots.txt"));
    copied++;
  }

  try {
    const sdkDir = dirname(themeRequire.resolve("@panomc/sdk/package.json"));
    copyTree(join(sdkDir, "core", "fonts"), join(staticDir, "assets", "fonts"));
  } catch {
    /* sdk not installed yet — next sync run picks the fonts up */
  }
  // Engine stylesheets (doc 03 sections 4.2, 4.6): generated, so unlike the branding assets above
  // they follow the engine version and are refreshed when their content changed.
  const cssDir = join(staticDir, "assets", "css");
  const copyCss = (from, name) => {
    if (!existsSync(from)) return;
    const to = join(cssDir, name);
    const content = readFileSync(from);
    if (existsSync(to) && readFileSync(to).equals(content)) return;
    mkdirSync(cssDir, { recursive: true });
    writeFileSync(to, content);
    copied++;
  };

  copyCss(join(engineAssets, "css", "pano-fallback.css"), "pano-fallback.css");
  copyCss(join(engineAssets, "css", "pano-fallback-legacy.css"), "pano-fallback-legacy.css");
  try {
    const sdkDir = dirname(themeRequire.resolve("@panomc/sdk/package.json"));
    copyCss(join(sdkDir, "core", "css", "pano-tokens.css"), "pano-tokens.css");
  } catch {
    /* sdk not installed yet — next sync run picks the tokens up */
  }

  // The theme's own copy first, then the engine's dependency: a theme that does not list the package still gets
  // the icon fallback sheet.
  const engineRequire = createRequire(import.meta.url);
  let faDir = null;
  for (const req of [themeRequire, engineRequire]) {
    try {
      faDir = dirname(req.resolve("@fortawesome/fontawesome-free/package.json"));
      break;
    } catch {
      /* try the next place */
    }
  }

  try {
    if (!faDir) throw new Error("fontawesome not installed");
    copyTree(join(faDir, "webfonts"), join(staticDir, "assets", "webfonts"));
    // its url(../webfonts/...) references resolve to the webfonts copied just above
    copyCss(join(faDir, "css", "all.min.css"), "pano-fallback-icons.css");
  } catch {
    /* fontawesome not installed yet — next sync run picks the webfonts up */
  }

  return copied;
}

// ---------------------------------------------------------------------------
// Route config (doc 01 section 9): `src/hooks.js` and one page pair per `routes.add` entry
// ---------------------------------------------------------------------------

const themeDir = process.cwd();
const themeConfigPath = join(themeDir, "theme.config.js");

/** @type {any} */
let themeConfig = {};
let configLoaded = true;

if (existsSync(themeConfigPath)) {
  try {
    themeConfig = (await import(pathToFileURL(themeConfigPath).href)).default ?? {};
  } catch (e) {
    // Keep the generated routes as they are rather than sweeping away what we cannot read.
    configLoaded = false;
    console.warn(
      `${pc.yellow("!")} theme-core sync: theme.config.js could not be imported (${e?.message ?? e}); ` +
        "routes.add is skipped and no stale files are removed this run",
    );
  }
}

/** Two paths with the same shape are the same route (`/p/[a]` and `/p/[b]`). */
const shapeOf = (path) =>
  path
    .split("/")
    .filter(Boolean)
    .map((part) => (part.startsWith("[...") ? "**" : part.startsWith("[") ? "*" : part))
    .join("/");

/** Route directories the engine already serves (catch-all plugin host excluded). */
function liveShapes(files) {
  const shapes = new Set();

  for (const file of files) {
    if (file.path.includes("[...path]")) continue;

    const parts = file.path.split("/").slice(0, -1).filter((part) => !/^\(.*\)$/.test(part));
    shapes.add(shapeOf("/" + parts.join("/")));
  }

  return shapes;
}

function routeConfigProblems(config, files) {
  const problems = [];
  const routes = config?.routes ?? {};

  try {
    createRouteMap({ rename: routes.rename, disable: routes.disable });
  } catch (e) {
    problems.push(e.message);
  }

  const live = liveShapes(files);
  const publicShapes = new Set(Object.values(routes.rename ?? {}).map((path) => shapeOf(path)));
  const seen = new Set();

  for (const [path, file] of Object.entries(routes.add ?? {})) {
    try {
      createRouteMap({ disable: [path] });
    } catch (e) {
      problems.push(`routes.add "${path}": ${e.message}`);
      continue;
    }

    const shape = shapeOf(path);

    if (shape === "posts" || shape.startsWith("posts/")) {
      problems.push(`routes.add "${path}": /posts is reserved for the posts feed`);
    } else if (path === "/" || live.has(shape)) {
      problems.push(`routes.add "${path}": the engine already serves this path; use views to redraw it, or rename it`);
    } else if (shape === "__pano" || shape.startsWith("__pano")) {
      problems.push(`routes.add "${path}": /__pano* is reserved`);
    } else if (publicShapes.has(shape)) {
      problems.push(`routes.add "${path}": a renamed route is already published at this path`);
    } else if (seen.has(shape)) {
      problems.push(`routes.add "${path}": two entries add the same route`);
    }
    seen.add(shape);

    if (typeof file !== "string" || !existsSync(join(themeDir, file))) {
      problems.push(`routes.add "${path}": page file ${JSON.stringify(file)} does not exist`);
    }
  }

  return problems;
}

/** `+page.svelte` and `+page.js` for one `routes.add` entry. */
function addedRouteFiles(path, file) {
  const directory = "(theme)" + (path === "/" ? "" : path);
  const fromRoute = (target) => {
    const rel = relative(dirname(join(routesDir, directory, "+page.js")), join(themeDir, target)).split(sep).join("/");

    return rel.startsWith(".") ? rel : "./" + rel;
  };
  const page = fromRoute(file);

  return [
    {
      path: `${directory}/+page.js`,
      content: `${HEADER_JS}import * as mod from "${page}";
import { themePageLoad } from "$pano/lib/themePageLoad.js";

export const load = themePageLoad(${JSON.stringify("route:" + path)}, mod);
`,
    },
    {
      path: `${directory}/+page.svelte`,
      content: `${HEADER_SVELTE}<script>
  import ThemePage from "${page}";

  export let data;
</script>

<ThemePage {data} />
`,
    },
  ];
}

const routesDir = join(process.cwd(), "src", "routes");

const routeProblems = configLoaded ? routeConfigProblems(themeConfig, BASE_FILES) : [];

if (routeProblems.length) {
  console.error(`${pc.red("✗")} theme-core sync: theme.config.js routes are not valid, nothing was written:`);
  for (const problem of routeProblems) console.error(`  - ${problem}`);
  process.exit(1);
}

const FILES = [
  ...BASE_FILES,
  ...(configLoaded ? Object.entries(themeConfig?.routes?.add ?? {}).flatMap(([path, file]) => addedRouteFiles(path, file)) : []),
];

/**
 * `src/hooks.js` (universal hooks): the reroute hook that maps a theme's public paths to the
 * canonical ones (doc 01 section 9). A hand-written hooks.js (no generated header) is never replaced.
 */
const HOOKS_FILE = {
  path: "hooks.js",
  content: existsSync(themeConfigPath)
    ? `${HEADER_JS}import themeConfig from "../theme.config.js";
import { createReroute, setRouteConfig } from "$pano/registry/routes.js";

// Module side effect, like the root layout: route() knows the renames on the server and the client.
setRouteConfig(themeConfig);

export const reroute = createReroute(themeConfig);
`
    : `${HEADER_JS}import { createReroute } from "$pano/registry/routes.js";

export const reroute = createReroute({});
`,
};


let written = 0;
let ejected = 0;

const known = new Set(FILES.map((f) => join(routesDir, f.path)));

const libDir = join(process.cwd(), "src", "lib");

const srcDir = join(process.cwd(), "src");

for (const [baseDir, files] of [
  [routesDir, FILES],
  [libDir, LIB_STUBS],
  [srcDir, [HOOKS_FILE]],
]) {
  for (const file of files) {
    const target = join(baseDir, file.path);

    if (
      existsSync(target) &&
      readFileSync(target, "utf-8").includes(EJECT_MARKER)
    ) {
      ejected++;
      continue;
    }

    if (file === HOOKS_FILE && existsSync(target) && !readFileSync(target, "utf-8").includes("AUTO-GENERATED by theme-core sync")) {
      console.warn(`${pc.yellow("!")} theme-core sync: src/hooks.js is hand-written and was left alone; it needs \`export const reroute = createReroute(themeConfig)\` for routes.rename / routes.disable to work`);
      ejected++;
      continue;
    }

    mkdirSync(dirname(target), { recursive: true });
    writeFileSync(target, file.content);
    written++;
  }
}

// Remove stale generated files (routes that no longer exist in core). Ejected
// and theme-invented files are left alone.
let removed = 0;
function sweep(dir) {
  if (!existsSync(dir)) return;
  for (const entry of readdirSync(dir)) {
    const p = join(dir, entry);
    if (statSync(p).isDirectory()) {
      sweep(p);
      if (readdirSync(p).length === 0) rmSync(p, { recursive: true });
    } else if (!known.has(p)) {
      const body = readFileSync(p, "utf-8");
      if (body.includes("AUTO-GENERATED by theme-core sync") && !body.includes(EJECT_MARKER)) {
        rmSync(p);
        removed++;
      }
    }
  }
}
if (configLoaded) {
  sweep(routesDir);
}

const langMerged = syncLang();
backfillTokens();
const assetsCopied = syncStaticAssets();

// Plugin contracts (doc 01 section 5): snapshots of the installed plugins, the changed views are printed.
try {
  pullContracts({ themeDir, log: (line) => console.log(`${pc.yellow("▲")} ${line}`) });
} catch (e) {
  console.warn(`${pc.yellow("!")} theme-core sync: plugin contracts were not refreshed (${e?.message ?? e})`);
}

// core-meta.json (doc 01 section 7): overrides, engine, supports, home, routes, controllers, ... The build
// writes it again into build/ before the fingerprint step.
let coreMeta = "kept";
if (configLoaded) {
  try {
    coreMeta = writeCoreMeta({ themeDir, config: themeConfig }).changed ? "written" : "unchanged";
  } catch (e) {
    console.warn(`${pc.yellow("!")} theme-core sync: core-meta.json was not written (${e?.message ?? e})`);
  }
}

console.log(
  `${pc.green("✓")} ${pc.bold("theme-core sync")} — ${written} shims written, ${ejected} ejected (kept), ${removed} stale removed, ${langMerged} lang files merged, ${assetsCopied} assets copied, core-meta.json ${coreMeta}`,
);
